CREATE TABLE IF NOT EXISTS "fraud_alert_comments" (
  "id" text PRIMARY KEY NOT NULL,
  "alert_id" text NOT NULL,
  "merchant_id" text NOT NULL,
  "author_name" text NOT NULL,
  "body" text NOT NULL,
  "created_at" timestamp DEFAULT now() NOT NULL,
  CONSTRAINT "fraud_alert_comments_alert_id_fraud_alerts_id_fk" FOREIGN KEY ("alert_id") REFERENCES "fraud_alerts"("id") ON DELETE CASCADE,
  CONSTRAINT "fraud_alert_comments_merchant_id_merchants_id_fk" FOREIGN KEY ("merchant_id") REFERENCES "merchants"("id")
);
CREATE INDEX IF NOT EXISTS "fac_alert_idx" ON "fraud_alert_comments" ("alert_id");
CREATE INDEX IF NOT EXISTS "fac_merchant_idx" ON "fraud_alert_comments" ("merchant_id");

